-- workspace's on its invoices; NULL for the workspace's, 0 for never charged a minimum.
ALTER TABLE client ADD COLUMN minimum_charge DECIMAL(19, 2);
-- Whether the line's price comes from its client's rate card for its unit type, so a draft's line follows the
-- card when a rate is changed; sending fixes the price on the line and clears this.
ALTER TABLE invoice_line ADD COLUMN card_priced BOOLEAN DEFAULT FALSE NOT NULL;
-- Whether the line was priced from the rates for its unit type (its client's rate card, or else the price list), at a
-- price already negotiated: it takes no share of the invoice discount. Unlike card_priced, sending keeps it.
ALTER TABLE invoice_line ADD COLUMN rate_priced BOOLEAN DEFAULT FALSE NOT NULL;
UPDATE invoice_line SET rate_priced = card_priced;
