      error: (e: HttpErrorResponse) => {
        const detail: unknown = e.error?.detail;
        this.lookupError.set(
          typeof detail === 'string' && detail ? detail : 'The invoice could not be opened.',
        );
        this.looking.set(false);
      },
    });
  }

